def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_towards(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_pos(key, default=None):
        v = observation.get(key, default)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return default

    sx_sy = get_pos("self_position", [0, 0])
    ox_oy = get_pos("opponent_position", sx_sy)
    sx, sy = sx_sy[0], sx_sy[1]
    ox, oy = ox_oy[0], ox_oy[1]

    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", "")

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_towards([sx, sy], [ox, oy])

        corners = [
            [0, 0],
            [0, h - 1 if h else 0],
            [w - 1 if w else 0, 0],
            [w - 1 if w else 0, h - 1 if h else 0],
        ]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, [ox, oy])
            if d > best:
                best = d
                target = c
        return step_towards([sx, sy], target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        best_target = None
        best_score = None
        for t in targets:
            if not (isinstance(t, (list, tuple)) and len(t) >= 2):
                continue
            d_self = manhattan([sx, sy], [t[0], t[1]])
            d_opp = manhattan([ox, oy], [t[0], t[1]])
            score = (d_self, -d_opp)
            if best_score is None or score < best_score:
                best_score = score
                best_target = [t[0], t[1]]
        if best_target is None:
            return step_away([sx, sy], [ox, oy]) if manhattan([sx, sy], [ox, oy]) <= 2 else [0, 0]
        return step_towards([sx, sy], best_target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    carrying = observation.get("carrying", observation.get("resource_count", 0))
    home = get_pos("home_base", None) or get_pos("base_position", None) or get_pos("spawn_position", None)

    if isinstance(carrying, (int, float)) and carrying > 0 and home is not None:
        return step_towards([sx, sy], home)

    best_target = None
    best_score = None
    for r in resources:
        if not (isinstance(r, (list, tuple)) and len(r) >= 2):
            continue
        d_self = manhattan([sx, sy], [r[0], r[1]])
        d_opp = manhattan([ox, oy], [r[0], r[1]])
        score = (d_self, d_opp)
        if best_score is None or score < best_score:
            best_score = score
            best_target = [r[0], r[1]]

    if best_target is not None:
        return step_towards([sx, sy], best_target)

    if home is not None and carrying:
        return step_towards([sx, sy], home)

    if manhattan([sx, sy], [ox, oy]) <= 1:
        return step_away([sx, sy], [ox, oy])

    patrol = observation.get("patrol_target")
    if isinstance(patrol, (list, tuple)) and len(patrol) >= 2:
        return step_towards([sx, sy], [patrol[0], patrol[1]])

    return [0, 0]

